import { spawn } from 'node:child_process';
import { once } from 'node:events';
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: ':memory:' }, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
const exited = once(child, 'exit');
let output = '';
try {
  const port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Launch timed out')), 10000);
    child.once('error', error => { clearTimeout(timer); reject(error); });
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/Workboard listening on port (\\d+)/);
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  const body = await response.text();
  if (response.status !== 200 || body !== '"'{\"status\":\"ok\"}') throw new Error("'`Unexpected health response: ${response.status} ${body}`);
  console.log(`npm start smoke check passed: HTTP ${response.status} ${body}`);
} finally {
  process.kill(-child.pid, '"'SIGTERM');
  await exited;
}
